-- 快递驿站出入库与滞留预警系统 数据库初始化脚本
-- 生成时间 2026-11-01 18:10:09
-- 仅操作本项目库 new_047，不影响其他通道

DROP DATABASE IF EXISTS `new_047`;
CREATE DATABASE `new_047` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `new_047`;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

DROP TABLE IF EXISTS `station`;
CREATE TABLE `station` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `station_no` varchar(32) DEFAULT NULL COMMENT '站点编号',
  `station_name` varchar(64) DEFAULT NULL COMMENT '站点名称',
  `address` varchar(160) DEFAULT NULL COMMENT '详细地址',
  `business_hours` varchar(48) DEFAULT NULL COMMENT '营业时间',
  `manager_id` bigint NOT NULL DEFAULT 0 COMMENT '负责人用户 ID',
  `phone` varchar(20) DEFAULT NULL COMMENT '联系电话',
  `capacity_total` int NOT NULL DEFAULT 0 COMMENT '总容量（位）',
  `status` varchar(16) DEFAULT NULL COMMENT '状态 启用/停用',
  `create_by` bigint NOT NULL DEFAULT 0 COMMENT '创建人',
  `version` int NOT NULL DEFAULT 0 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_station_station_no` (`station_no`),
  KEY `idx_station_manager_id` (`manager_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='站点';

DROP TABLE IF EXISTS `shelf`;
CREATE TABLE `shelf` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `shelf_no` varchar(16) DEFAULT NULL COMMENT '货架编号 A-01',
  `station_id` bigint NOT NULL DEFAULT 0 COMMENT '所属站点',
  `area_code` varchar(8) DEFAULT NULL COMMENT '区域 A/B/C/D',
  `shelf_type` varchar(16) DEFAULT NULL COMMENT '适用件型 小件/中件/大件/异形件',
  `capacity` int NOT NULL DEFAULT 0 COMMENT '容量（位）',
  `used_count` int NOT NULL DEFAULT 0 COMMENT '已占用位数',
  `level_count` int NOT NULL DEFAULT 0 COMMENT '层位数',
  `status` varchar(16) DEFAULT NULL COMMENT '状态 可用/满载/停用',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `create_by` bigint NOT NULL DEFAULT 0 COMMENT '创建人',
  `version` int NOT NULL DEFAULT 0 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_shelf_shelf_no` (`shelf_no`),
  KEY `idx_shelf_station_id` (`station_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='货架';

DROP TABLE IF EXISTS `shelf_level`;
CREATE TABLE `shelf_level` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `shelf_id` bigint NOT NULL DEFAULT 0 COMMENT '货架 ID',
  `level_no` int NOT NULL DEFAULT 0 COMMENT '层号',
  `capacity` int NOT NULL DEFAULT 0 COMMENT '本层容量',
  `used_count` int NOT NULL DEFAULT 0 COMMENT '本层已用',
  `status` varchar(16) DEFAULT NULL COMMENT '状态 可用/停用',
  `create_by` bigint NOT NULL DEFAULT 0 COMMENT '创建人',
  `version` int NOT NULL DEFAULT 0 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_shelf_level_shelf_id` (`shelf_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='货架层位';

DROP TABLE IF EXISTS `express_company`;
CREATE TABLE `express_company` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `company_code` varchar(16) DEFAULT NULL COMMENT '公司编码 SF/JD/ZTO',
  `company_name` varchar(64) DEFAULT NULL COMMENT '公司名称',
  `contact` varchar(32) DEFAULT NULL COMMENT '对接人',
  `phone` varchar(20) DEFAULT NULL COMMENT '联系电话',
  `area_code` varchar(8) DEFAULT NULL COMMENT '约定分区 A/B/C/D',
  `status` varchar(16) DEFAULT NULL COMMENT '状态 合作中/已停用',
  `create_by` bigint NOT NULL DEFAULT 0 COMMENT '创建人',
  `version` int NOT NULL DEFAULT 0 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_express_company_company_code` (`company_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='快递公司';

DROP TABLE IF EXISTS `courier`;
CREATE TABLE `courier` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `courier_no` varchar(32) DEFAULT NULL COMMENT '快递员工号',
  `courier_name` varchar(32) DEFAULT NULL COMMENT '姓名',
  `company_id` bigint NOT NULL DEFAULT 0 COMMENT '所属快递公司',
  `phone` varchar(20) DEFAULT NULL COMMENT '手机号',
  `station_id` bigint NOT NULL DEFAULT 0 COMMENT '服务站点',
  `user_id` bigint NOT NULL DEFAULT 0 COMMENT '关联登录账号',
  `status` varchar(16) DEFAULT NULL COMMENT '状态 在职/离职',
  `create_by` bigint NOT NULL DEFAULT 0 COMMENT '创建人',
  `version` int NOT NULL DEFAULT 0 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_courier_courier_no` (`courier_no`),
  KEY `idx_courier_company_id` (`company_id`),
  KEY `idx_courier_station_id` (`station_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='快递员';

DROP TABLE IF EXISTS `handover_batch`;
CREATE TABLE `handover_batch` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `batch_no` varchar(32) DEFAULT NULL COMMENT '批次号 JByyyymmdd-序号',
  `company_id` bigint NOT NULL DEFAULT 0 COMMENT '快递公司',
  `courier_id` bigint NOT NULL DEFAULT 0 COMMENT '快递员',
  `station_id` bigint NOT NULL DEFAULT 0 COMMENT '站点',
  `arrive_time` datetime DEFAULT NULL COMMENT '到站时间',
  `total_count` int NOT NULL DEFAULT 0 COMMENT '交接单总数',
  `received_count` int NOT NULL DEFAULT 0 COMMENT '实际接收数',
  `rejected_count` int NOT NULL DEFAULT 0 COMMENT '拒收数',
  `diff_count` int NOT NULL DEFAULT 0 COMMENT '差异件数',
  `diff_note` varchar(500) DEFAULT NULL COMMENT '差异说明',
  `status` varchar(24) DEFAULT NULL COMMENT '状态 交接中/已确认/差异待确认',
  `confirm_time` datetime DEFAULT NULL COMMENT '双方确认时间',
  `handler_id` bigint NOT NULL DEFAULT 0 COMMENT '驿站经办人',
  `create_by` bigint NOT NULL DEFAULT 0 COMMENT '创建人',
  `version` int NOT NULL DEFAULT 0 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_handover_batch_batch_no` (`batch_no`),
  KEY `idx_handover_batch_company_id` (`company_id`),
  KEY `idx_handover_batch_courier_id` (`courier_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='交接批次';

DROP TABLE IF EXISTS `handover_item`;
CREATE TABLE `handover_item` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `batch_id` bigint NOT NULL DEFAULT 0 COMMENT '批次 ID',
  `waybill_no` varchar(50) DEFAULT NULL COMMENT '运单号',
  `receiver_name` varchar(32) DEFAULT NULL COMMENT '收件人',
  `item_type` varchar(16) DEFAULT NULL COMMENT '件型',
  `scan_time` datetime DEFAULT NULL COMMENT '扫描时间',
  `result` varchar(16) DEFAULT NULL COMMENT '接收结果 已接收/拒收/差异',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `create_by` bigint NOT NULL DEFAULT 0 COMMENT '创建人',
  `version` int NOT NULL DEFAULT 0 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_handover_item_batch_id` (`batch_id`),
  KEY `idx_handover_item_waybill_no` (`waybill_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='批次明细';

DROP TABLE IF EXISTS `parcel`;
CREATE TABLE `parcel` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `waybill_no` varchar(50) DEFAULT NULL COMMENT '运单号（站内唯一）',
  `company_id` bigint NOT NULL DEFAULT 0 COMMENT '快递公司',
  `receiver_name` varchar(32) DEFAULT NULL COMMENT '收件人',
  `receiver_phone` varchar(20) DEFAULT NULL COMMENT '收件人手机号',
  `phone_tail` varchar(8) DEFAULT NULL COMMENT '手机号后四位',
  `item_type` varchar(16) DEFAULT NULL COMMENT '件型 小件/中件/大件/异形件',
  `size_desc` varchar(48) DEFAULT NULL COMMENT '尺寸描述',
  `special_flag` varchar(24) DEFAULT NULL COMMENT '特殊件标记 无/贵重件/生鲜冷藏/易碎品',
  `station_id` bigint NOT NULL DEFAULT 0 COMMENT '所属站点',
  `batch_id` bigint NOT NULL DEFAULT 0 COMMENT '交接批次',
  `shelf_id` bigint NOT NULL DEFAULT 0 COMMENT '货架 ID',
  `shelf_no` varchar(16) DEFAULT NULL COMMENT '货架编号（冗余）',
  `pickup_code` varchar(12) DEFAULT NULL COMMENT '取件码',
  `status` varchar(24) DEFAULT NULL COMMENT '状态 待上架/在库/已通知/已取件/待退回/已退件/异常件',
  `arrive_time` datetime DEFAULT NULL COMMENT '到站入库时间',
  `shelf_time` datetime DEFAULT NULL COMMENT '上架时间',
  `notify_count` int NOT NULL DEFAULT 0 COMMENT '已通知次数',
  `last_notify_time` datetime DEFAULT NULL COMMENT '最后通知时间',
  `pickup_time` datetime DEFAULT NULL COMMENT '取件时间',
  `retention_days` int NOT NULL DEFAULT 0 COMMENT '在库天数',
  `handler_id` bigint NOT NULL DEFAULT 0 COMMENT '经办人',
  `cover_image` varchar(200) DEFAULT NULL COMMENT '包裹照片（相对路径）',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `create_by` bigint NOT NULL DEFAULT 0 COMMENT '创建人',
  `version` int NOT NULL DEFAULT 0 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_parcel_waybill_no` (`waybill_no`),
  KEY `idx_parcel_company_id` (`company_id`),
  KEY `idx_parcel_station_id` (`station_id`),
  KEY `idx_parcel_shelf_id` (`shelf_id`),
  KEY `idx_parcel_pickup_code` (`pickup_code`),
  KEY `idx_parcel_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='快件';

DROP TABLE IF EXISTS `shelf_record`;
CREATE TABLE `shelf_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `parcel_id` bigint NOT NULL DEFAULT 0 COMMENT '快件 ID',
  `action_type` varchar(16) DEFAULT NULL COMMENT '动作 上架/移库/下架',
  `shelf_id` bigint NOT NULL DEFAULT 0 COMMENT '目标货架',
  `shelf_no` varchar(16) DEFAULT NULL COMMENT '目标货架编号',
  `from_shelf_no` varchar(16) DEFAULT NULL COMMENT '原货架编号',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '操作人',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `create_by` bigint NOT NULL DEFAULT 0 COMMENT '创建人',
  `version` int NOT NULL DEFAULT 0 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_shelf_record_parcel_id` (`parcel_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='上架记录';

DROP TABLE IF EXISTS `notify_record`;
CREATE TABLE `notify_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `parcel_id` bigint NOT NULL DEFAULT 0 COMMENT '快件 ID',
  `notify_type` varchar(16) DEFAULT NULL COMMENT '方式 电话/站内消息/短信',
  `content` varchar(500) DEFAULT NULL COMMENT '通知内容',
  `result` varchar(24) DEFAULT NULL COMMENT '结果 已通知/无人接听/失败',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '经办人',
  `notify_time` datetime DEFAULT NULL COMMENT '通知时间',
  `create_by` bigint NOT NULL DEFAULT 0 COMMENT '创建人',
  `version` int NOT NULL DEFAULT 0 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_notify_record_parcel_id` (`parcel_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='通知记录';

DROP TABLE IF EXISTS `pickup_record`;
CREATE TABLE `pickup_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `parcel_id` bigint NOT NULL DEFAULT 0 COMMENT '快件 ID',
  `pickup_type` varchar(16) DEFAULT NULL COMMENT '取件方式 本人/代取',
  `verify_type` varchar(24) DEFAULT NULL COMMENT '核验方式',
  `pickup_person` varchar(32) DEFAULT NULL COMMENT '取件人',
  `pickup_phone` varchar(20) DEFAULT NULL COMMENT '取件人手机号',
  `proxy_id` bigint NOT NULL DEFAULT 0 COMMENT '代取授权 ID',
  `operator_id` bigint NOT NULL DEFAULT 0 COMMENT '经办员工',
  `pickup_time` datetime DEFAULT NULL COMMENT '取件时间',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `create_by` bigint NOT NULL DEFAULT 0 COMMENT '创建人',
  `version` int NOT NULL DEFAULT 0 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_pickup_record_parcel_id` (`parcel_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='取件记录';

DROP TABLE IF EXISTS `proxy_auth`;
CREATE TABLE `proxy_auth` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `parcel_id` bigint NOT NULL DEFAULT 0 COMMENT '快件 ID（0 表示按手机号全量授权）',
  `receiver_name` varchar(32) DEFAULT NULL COMMENT '收件人',
  `receiver_phone` varchar(20) DEFAULT NULL COMMENT '收件人手机号',
  `proxy_name` varchar(32) DEFAULT NULL COMMENT '代取人姓名',
  `proxy_phone` varchar(20) DEFAULT NULL COMMENT '代取人手机号',
  `auth_type` varchar(16) DEFAULT NULL COMMENT '授权方式 线上登记/现场登记',
  `valid_until` datetime DEFAULT NULL COMMENT '有效期至',
  `status` varchar(16) DEFAULT NULL COMMENT '状态 有效/已使用/已失效',
  `create_by` bigint NOT NULL DEFAULT 0 COMMENT '创建人',
  `version` int NOT NULL DEFAULT 0 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_proxy_auth_receiver_phone` (`receiver_phone`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='代取授权';

DROP TABLE IF EXISTS `retention_warning`;
CREATE TABLE `retention_warning` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `parcel_id` bigint NOT NULL DEFAULT 0 COMMENT '快件 ID',
  `retention_days` int NOT NULL DEFAULT 0 COMMENT '在库天数',
  `level` varchar(24) DEFAULT NULL COMMENT '等级 正常/即将滞留/已滞留/待退回',
  `notify_count` int NOT NULL DEFAULT 0 COMMENT '已通知次数',
  `handle_status` varchar(16) DEFAULT NULL COMMENT '处理状态 待处理/已催取/已处理',
  `handle_note` varchar(300) DEFAULT NULL COMMENT '处理备注',
  `handle_time` datetime DEFAULT NULL COMMENT '处理时间',
  `handler_id` bigint NOT NULL DEFAULT 0 COMMENT '处理人',
  `create_by` bigint NOT NULL DEFAULT 0 COMMENT '创建人',
  `version` int NOT NULL DEFAULT 0 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_retention_warning_parcel_id` (`parcel_id`),
  KEY `idx_retention_warning_level` (`level`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='滞留预警';

DROP TABLE IF EXISTS `return_apply`;
CREATE TABLE `return_apply` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `apply_no` varchar(32) DEFAULT NULL COMMENT '退件单号 TJyyyymmdd-序号',
  `parcel_id` bigint NOT NULL DEFAULT 0 COMMENT '快件 ID',
  `waybill_no` varchar(50) DEFAULT NULL COMMENT '运单号（冗余）',
  `reason_type` varchar(24) DEFAULT NULL COMMENT '原因 拒收/超期未取/地址错误/破损退件/收件人要求',
  `reason` varchar(300) DEFAULT NULL COMMENT '原因说明',
  `apply_user_id` bigint NOT NULL DEFAULT 0 COMMENT '申请人',
  `approve_user_id` bigint NOT NULL DEFAULT 0 COMMENT '确认人（负责人）',
  `approve_time` datetime DEFAULT NULL COMMENT '确认时间',
  `status` varchar(24) DEFAULT NULL COMMENT '状态 待负责人确认/待交接/已交接/已驳回',
  `create_by` bigint NOT NULL DEFAULT 0 COMMENT '创建人',
  `version` int NOT NULL DEFAULT 0 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_return_apply_apply_no` (`apply_no`),
  KEY `idx_return_apply_parcel_id` (`parcel_id`),
  KEY `idx_return_apply_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='退件申请';

DROP TABLE IF EXISTS `return_handover`;
CREATE TABLE `return_handover` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `apply_id` bigint NOT NULL DEFAULT 0 COMMENT '退件申请 ID',
  `courier_id` bigint NOT NULL DEFAULT 0 COMMENT '交接快递员',
  `plan_count` int NOT NULL DEFAULT 0 COMMENT '应退件数',
  `actual_count` int NOT NULL DEFAULT 0 COMMENT '实收件数',
  `handover_time` datetime DEFAULT NULL COMMENT '交接时间',
  `receiver_name` varchar(32) DEFAULT NULL COMMENT '接收人签字',
  `voucher_file` varchar(200) DEFAULT NULL COMMENT '凭证图片路径',
  `remark` varchar(200) DEFAULT NULL COMMENT '备注',
  `create_by` bigint NOT NULL DEFAULT 0 COMMENT '创建人',
  `version` int NOT NULL DEFAULT 0 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  KEY `idx_return_handover_apply_id` (`apply_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='退件交接';

DROP TABLE IF EXISTS `exception_parcel`;
CREATE TABLE `exception_parcel` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `exception_no` varchar(32) DEFAULT NULL COMMENT '异常单号 YCyyyymmdd-序号',
  `parcel_id` bigint NOT NULL DEFAULT 0 COMMENT '快件 ID',
  `waybill_no` varchar(50) DEFAULT NULL COMMENT '运单号（冗余）',
  `ex_type` varchar(24) DEFAULT NULL COMMENT '类型 外包装破损/内件破损/渗漏/错件/丢失/信息不符/疑似重复件',
  `find_stage` varchar(24) DEFAULT NULL COMMENT '发现环节 入库扫描/上架核对/取件核验/在库盘点',
  `duty_side` varchar(24) DEFAULT NULL COMMENT '责任方 快递公司/驿站/收件人/待认定',
  `description` varchar(500) DEFAULT NULL COMMENT '情况说明',
  `images` varchar(500) DEFAULT NULL COMMENT '现场图片（逗号分隔相对路径）',
  `handle_process` varchar(1000) DEFAULT NULL COMMENT '处理过程',
  `result` varchar(300) DEFAULT NULL COMMENT '处理结果',
  `status` varchar(24) DEFAULT NULL COMMENT '状态 待处理/处理中/待负责人审核/已关闭',
  `registrar_id` bigint NOT NULL DEFAULT 0 COMMENT '登记人',
  `audit_user_id` bigint NOT NULL DEFAULT 0 COMMENT '审核人',
  `audit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `create_by` bigint NOT NULL DEFAULT 0 COMMENT '创建人',
  `version` int NOT NULL DEFAULT 0 COMMENT '版本号（并发校验）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0 否 1 是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_exception_parcel_exception_no` (`exception_no`),
  KEY `idx_exception_parcel_parcel_id` (`parcel_id`),
  KEY `idx_exception_parcel_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='异常件';

DROP TABLE IF EXISTS `stocktake_task`;
CREATE TABLE `stocktake_task` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `task_no` varchar(32) DEFAULT NULL COMMENT '任务号 PDyyyymmdd-序号',
  `station_id` bigint NOT NULL DEFAULT 0 COMMENT '站点',
