-- =====================================================================
-- 数据一致性与口径补丁（幂等，重复导入不产生副作用）
-- 1) 站点负责人与 sys_user 对齐：manager01→ST-001，manager02→ST-002
-- 2) 货架占用按实际在库件重算，容量收敛到真实量级，形成「充足/紧张/满载」梯度
-- 3) 头像按 8 张种子图轮换（单实体上限，避免一人一张撑爆目录）
-- 4) 站内消息类型对齐需求文档（待审批/即将超时/已退回/待验收/处理完成），并补齐各角色消息
-- 5) courier.user_id 与 sys_user 对齐（原种子整体偏移一位，快递员看不到本人批次）
-- =====================================================================
UPDATE station SET manager_id = 2 WHERE id = 1;
UPDATE station SET manager_id = 3 WHERE id = 2;

UPDATE shelf s SET used_count = (
  SELECT COUNT(*) FROM parcel p WHERE p.shelf_id = s.id AND p.status IN ('在库','已通知') AND p.deleted = 0
) WHERE s.deleted = 0 AND s.status <> '停用';
UPDATE shelf SET capacity = used_count + 2 + (id % 4) WHERE status <> '停用';
UPDATE shelf SET capacity = GREATEST(used_count, 1) WHERE status <> '停用' AND id IN (4, 8, 12, 18);
UPDATE shelf SET status = CASE WHEN used_count >= capacity THEN '满载' ELSE '可用' END WHERE status <> '停用';

UPDATE sys_user SET avatar = CONCAT('/uploads/seed/avatar/', LPAD(((id-1) % 8) + 1, 2, '0'), '.jpg') WHERE deleted = 0;

UPDATE sys_message SET msg_type = CASE id
  WHEN 1 THEN '待审批'   WHEN 2 THEN '即将超时' WHEN 3 THEN '待审批'
  WHEN 4 THEN '待审批'   WHEN 5 THEN '处理完成' WHEN 6 THEN '即将超时'
  WHEN 7 THEN '处理完成' WHEN 8 THEN '处理完成' WHEN 9 THEN '待审批'
  WHEN 10 THEN '处理完成' ELSE msg_type END
WHERE id BETWEEN 1 AND 10;


UPDATE courier SET user_id = 9 + id WHERE id BETWEEN 1 AND 6;

